  ["diff", "git diff -- tools/coverage/run.py tools/coverage/python_run.py .github/workflows/test.yml"],
  ["status", "git status --short"]
];
const rs = await Promise.allSettled(cmds.map(async ([name,cmd]) => ({name, ...(await tools.exec_command({cmd,workdir:"/Users/thomi/.codex/worktrees/04638663-839c-4e0a-9303-5b0278f98cd0/entire-brain",yield_time_ms:10000,max_output_tokens:10000}))})));
for (const x of rs) text(x.status === "fulfilled" ? `--- ${x.value.name} ---\n${x.value.output}` : `--- rejected ---\n${x.reason}`);

